#!/usr/bin/env bash
#
# install-boot-firmware-notices.sh: copyright files for the pinned Armbian firmware
# and U-Boot packages, which ship without one.
#
# Run by the app layer (mkosi.images/app/mkosi.postinst.chroot) after the other
# notice installers and before the doc prune, which keeps files named copyright.
# It reads only the static, checksummed files in boot-firmware/ (generated by
# tools/generate-boot-firmware-notices.py) and the installed tree: the dpkg
# status, .list and .md5sums files are read as text and installed files are only
# hashed. No network access, no package tool and nothing from the image runs.
#
# For each covered package that dpkg records as installed, the exact identity is
# checked before anything is written: version and architecture, the sha256 of its
# md5sums control file (which pins the archive's file list), every installed file
# against its sha256 (missing required files, changed bytes, symlinks and files
# the package database lists but the tables do not are refused), and the
# verbatim texts inside the payloads. The firmware file is completed with a list
# of every firmware file of the package, shipped or removed, with the source
# entry for its exact bytes. Other linux-u-boot-* and armbian-firmware* packages
# are logged as uncovered; nothing is written for them.
#
# Test seams: LICENCE_NOTICES_DESTROOT (install prefix, default /),
# BOOT_FIRMWARE_NOTICES_BASE (payload directory).
#
# shellcheck shell=bash

set -euo pipefail

log() { printf '[boot-firmware-notices] %s\n' "$*" >&2; }
die() { log "FATAL: $*"; exit 1; }

HERE="$(CDPATH='' cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd)"
BASE="${BOOT_FIRMWARE_NOTICES_BASE:-${HERE}/boot-firmware}"
DEST="${LICENCE_NOTICES_DESTROOT:-}"
WORK="$(mktemp -d)"
trap 'rm -rf "${WORK}"' EXIT
SHA_RE='^[0-9a-f]{64}$'
RULE='=============================================================================='

# --- 1. Static payloads, exactly as generated -----------------------------------
[[ -f "${BASE}/SHA256SUMS" && ! -L "${BASE}/SHA256SUMS" ]] || die "missing ${BASE}/SHA256SUMS"
expected='SHA256SUMS armbian-firmware-full.txt firmware-files.tsv identity.tsv inputs.json linux-u-boot-rock-5b-plus-edge.txt texts.tsv '
listed="$(awk '{print $2}' "${BASE}/SHA256SUMS" | sort | tr '\n' ' ')"
[[ "SHA256SUMS ${listed}" == "${expected}" ]] || die "SHA256SUMS lists '${listed}', expected '${expected#SHA256SUMS }'"
for name in ${expected}; do
  [[ -f "${BASE}/${name}" && ! -L "${BASE}/${name}" ]] || die "payload file ${name} is missing or a symlink"
done
if ! (cd "${BASE}" && sha256sum --check --strict SHA256SUMS) > "${WORK}/sums" 2>&1; then
  die "boot firmware notice payloads do not match SHA256SUMS: $(grep -v ': OK$' "${WORK}/sums" | tr '\n' ' ')"
fi

# Every verbatim text inside a payload still has its pinned bytes.
declare -A text_count=()
while IFS=$'\t' read -r payload offset bytes sum blob source commit path extra || [[ -n "${payload:-}" ]]; do
  [[ -z "${payload}" || "${payload}" == \#* ]] && continue
  [[ "${offset}" =~ ^[0-9]+$ && "${bytes}" =~ ^[1-9][0-9]*$ && "${sum}" =~ ${SHA_RE} && "${blob}" =~ ^[0-9a-f]{40}$ \
     && -n "${source}" && "${commit}" =~ ^[0-9a-f]{40}$ && -n "${path}" && -z "${extra}" ]] \
    || die "malformed texts.tsv row for '${path:-?}'"
  [[ -f "${BASE}/${payload}" ]] || die "texts.tsv names unknown payload ${payload}"
  actual="$(head -c "$((offset + bytes))" "${BASE}/${payload}" | tail -c "${bytes}" | sha256sum | awk '{print $1}')"
  [[ "${actual}" == "${sum}" ]] || die "verbatim text ${path} (${source}) inside ${payload} changed"
  text_count[${payload}]=$(( ${text_count[${payload}]:-0} + 1 ))
done < "${BASE}/texts.tsv"

# --- 2. Covered identities ---------------------------------------------------------
declare -A pkg_version=() pkg_arch=() pkg_md5=() pkg_payload=()
file_rows=()
fw_pkg='' fw_prefix='' fw_table='' loader_row=''
while IFS=$'\t' read -r kind a b c d e extra || [[ -n "${kind:-}" ]]; do
  [[ -z "${kind}" || "${kind}" == \#* ]] && continue
  [[ -z "${extra}" ]] || die "malformed identity.tsv row: too many fields"
  case "${kind}" in
    package)
      [[ -n "${a}" && -n "${b}" && -n "${c}" && "${d}" =~ ${SHA_RE} && "${e}" == "${a}.txt" ]] \
        || die "malformed identity.tsv package row for '${a}'"
      (( ${text_count[${e}]:-0} > 0 )) || die "payload ${e} has no verbatim texts"
      pkg_version[${a}]="${b}" pkg_arch[${a}]="${c}" pkg_md5[${a}]="${d}" pkg_payload[${a}]="${e}"
      ;;
    file)
      [[ -n "${pkg_version[${a}]:-}" && "${b}" == /* && "${b}" != *'/../'* && "${c}" =~ ${SHA_RE} \
         && ( "${d}" == required || "${d}" == optional ) && -z "${e}" ]] \
        || die "malformed identity.tsv file row '${b}'"
      file_rows+=("${a}"$'\t'"${b}"$'\t'"${c}"$'\t'"${d}")
      ;;
    firmware)
      [[ -z "${fw_pkg}" && -n "${pkg_version[${a}]:-}" && "${b}" == lib/firmware/ && "${c}" == firmware-files.tsv && -z "${d}" ]] \
        || die "malformed or repeated identity.tsv firmware row"
      fw_pkg="${a}" fw_prefix="${b}" fw_table="${BASE}/${c}"
      ;;
    loader)
      [[ -z "${loader_row}" && -n "${pkg_version[${a}]:-}" && "${c}" =~ ${SHA_RE} && -z "${d}" ]] \
        || die "malformed or repeated identity.tsv loader row"
      loader_row="${a}"$'\t'"${b}"$'\t'"${c}"
      ;;
    *) die "unknown identity.tsv row kind '${kind}'" ;;
  esac
done < "${BASE}/identity.tsv"
[[ -n "${fw_pkg}" && -n "${loader_row}" ]] || die "identity.tsv lacks its firmware or loader row"
grep -Fxq "${loader_row}"$'\trequired' <(printf '%s\n' "${file_rows[@]}") \
  || die "the loader row does not match a required file row"

# --- 3. Installed package database, read as text --------------------------------------
status_file="${DEST}/var/lib/dpkg/status"
[[ -f "${status_file}" && ! -L "${status_file}" ]] || die "cannot read ${status_file}; refusing to guess the installed packages"
awk 'BEGIN { RS = ""; FS = "\n"; OFS = "\t" }
  { p = s = v = a = ""
    for (i = 1; i <= NF; i++) {
      if ($i ~ /^Package: /) p = substr($i, 10)
      else if ($i ~ /^Status: /) s = substr($i, 9)
      else if ($i ~ /^Version: /) v = substr($i, 10)
      else if ($i ~ /^Architecture: /) a = substr($i, 15)
    }
    if (p != "") print p, s, v, a }' "${status_file}" > "${WORK}/status"

installed=()
for pkg in $(printf '%s\n' "${!pkg_version[@]}" | sort); do
  mapfile -t records < <(awk -F'\t' -v p="${pkg}" '$1 == p' "${WORK}/status")
  if (( ${#records[@]} == 0 )); then
    log "${pkg} is not installed in this image; skipped"
    continue
  fi
  (( ${#records[@]} == 1 )) || die "${pkg} has ${#records[@]} dpkg records; not a covered identity"
  IFS=$'\t' read -r _ status version arch <<< "${records[0]}"
  # Status is "<selection> <flag> <state>"; a hold or other selection does not
  # change what is installed, a non-ok flag or an unfinished state does.
  case "${status}" in
    install' ok installed' | hold' ok installed') ;;
    *' ok not-installed' | *' ok config-files') log "${pkg} is not installed in this image (${status}); skipped"; continue ;;
    *) die "${pkg} is in dpkg state '${status}'; refusing to guess its identity" ;;
  esac
  [[ "${version}" == "${pkg_version[${pkg}]}" && "${arch}" == "${pkg_arch[${pkg}]}" ]] \
    || die "${pkg} ${version} (${arch}) is installed, but the notices cover ${pkg_version[${pkg}]} (${pkg_arch[${pkg}]}); regenerate them for this pin"
  info="${DEST}/var/lib/dpkg/info/${pkg}"
  for f in "${info}.md5sums" "${info}.list"; do
    [[ -f "${f}" && ! -L "${f}" ]] || die "${f} is missing or a symlink; cannot establish ${pkg}'s file list"
  done
  [[ "$(sha256sum < "${info}.md5sums" | awk '{print $1}')" == "${pkg_md5[${pkg}]}" ]] \
    || die "${pkg} ${version}: installed md5sums differ from the pinned archive's; not the archive these notices describe"
  installed+=("${pkg}")
done
while IFS=$'\t' read -r pkg status version _; do
  [[ "${status}" == *' ok installed' && -z "${pkg_version[${pkg}]:-}" ]] || continue
  [[ "${pkg}" == linux-u-boot-* || "${pkg}" == armbian-firmware* ]] || continue
  log "uncovered: ${pkg} ${version} has no source mapping here; no copyright file is written for it"
done < "${WORK}/status"
(( ${#installed[@]} > 0 )) || { log "no covered package is installed; nothing to do"; exit 0; }

# Refuse to read or write through a symlinked directory below DEST.
no_symlink_dirs() { # <absolute path below DEST>
  local rest="${1#/}" dir="${DEST}"
  while [[ "${rest}" == */* ]]; do
    dir+="/${rest%%/*}"
    rest="${rest#*/}"
    [[ ! -L "${dir}" ]] || die "${dir} is a symlink; refusing to follow it"
  done
}

# --- 4. Installed files of each package ---------------------------------------------
declare -A known=()
for row in "${file_rows[@]}"; do
  IFS=$'\t' read -r pkg path sum kind <<< "${row}"
  [[ " ${installed[*]} " == *" ${pkg} "* ]] || continue
  known["${pkg}:${path}"]=1
  file="${DEST}${path}"
  no_symlink_dirs "${path}"
  grep -Fxq -- "${path}" "${DEST}/var/lib/dpkg/info/${pkg}.list" \
    || die "${pkg}: ${path} is not in its dpkg file list; not the pinned archive"
  if [[ -L "${file}" ]]; then
    die "${pkg}: ${path} is a symlink, not the pinned file"
  elif [[ -f "${file}" ]]; then
    [[ "$(sha256sum < "${file}" | awk '{print $1}')" == "${sum}" ]] || die "${pkg}: ${path} differs from the pinned archive"
  elif [[ -e "${file}" ]]; then
    die "${pkg}: ${path} is not a regular file"
  elif [[ "${kind}" == required ]]; then
    die "${pkg}: ${path} is missing; the installation is partial"
  fi
done
# Every regular file the package database lists must be one of the pinned files.
for pkg in "${installed[@]}"; do
  while IFS= read -r line; do
    if [[ "${pkg}" == "${fw_pkg}" && ( "${line}" == /lib/firmware/* || "${line}" == /usr/lib/firmware/* ) ]]; then
      continue
    fi
    if [[ -f "${DEST}${line}" && ! -L "${DEST}${line}" && -z "${known["${pkg}:${line}"]:-}" ]]; then
      die "${pkg}: ${line} is in its dpkg file list but not in identity.tsv"
    fi
  done < "${DEST}/var/lib/dpkg/info/${pkg}.list"
done

# --- 5. Firmware files ---------------------------------------------------------------
fw_rows=()
if [[ " ${installed[*]} " == *" ${fw_pkg} "* ]]; then
  for dir in /usr /usr/lib /usr/lib/firmware; do
    [[ -d "${DEST}${dir}" && ! -L "${DEST}${dir}" ]] || die "${DEST}${dir} is not a real directory"
  done
  [[ -L "${DEST}/lib" && "$(readlink "${DEST}/lib")" == usr/lib ]] \
    || die "${DEST}/lib is not the merged-/usr symlink to usr/lib; the firmware paths cannot be resolved"
  fw="${DEST}/usr/lib/firmware"
  declare -A fw_sum=() fw_listed=() dirs=()
  while IFS=$'\t' read -r path sum cls cover blob origin extra || [[ -n "${path:-}" ]]; do
    [[ -z "${path}" || "${path}" == \#* ]] && continue
    [[ "${path}" != /* && "${path}" != *'/../'* && "${path}" != ../* && "${sum}" =~ ${SHA_RE} \
       && "${cls}" =~ ^(upstream|upstream-other-path|armbian-changed|armbian-only)$ && -n "${cover}" \
       && "${blob}" =~ ^[0-9a-f]{40}$ && -n "${origin}" && -z "${extra}" ]] \
      || die "malformed firmware-files.tsv row for '${path}'"
    [[ -z "${fw_sum[${path}]:-}" ]] || die "firmware-files.tsv repeats ${path}"
    fw_sum[${path}]="${sum}"
    fw_rows+=("${path}"$'\t'"${cls}"$'\t'"${cover}")
    [[ "${path}" == */* ]] && dirs[${path%/*}]=1
  done < "${fw_table}"
  (( ${#fw_rows[@]} > 0 )) || die "firmware-files.tsv is empty"
  for dir in "${!dirs[@]}"; do
    sub=''
    rest="${dir}/"
    while [[ "${rest}" == */* ]]; do
      sub+="${sub:+/}${rest%%/*}"
      rest="${rest#*/}"
      [[ ! -L "${fw}/${sub}" ]] || die "firmware directory ${sub} is a symlink; refusing to follow it"
    done
  done

  # Package file list: every listed regular file must be pinned, and every pinned file listed.
  while IFS= read -r line; do
    case "${line}" in
      /lib/"${fw_prefix#lib/}"?* | /usr/lib/"${fw_prefix#lib/}"?*) rel="${line#*/firmware/}" ;;
      *) continue ;;
    esac
    fw_listed[${rel}]=1
    if [[ -f "${fw}/${rel}" && ! -L "${fw}/${rel}" && -z "${fw_sum[${rel}]:-}" ]]; then
      die "${fw_pkg}: firmware file ${rel} is in its dpkg file list but not in firmware-files.tsv"
    fi
  done < "${DEST}/var/lib/dpkg/info/${fw_pkg}.list"

  present=()
  for row in "${fw_rows[@]}"; do
    path="${row%%$'\t'*}"
    [[ -n "${fw_listed[${path}]:-}" ]] || die "${fw_pkg}: ${path} is pinned but not in its dpkg file list"
    if [[ -L "${fw}/${path}" ]]; then
      die "${fw_pkg}: firmware file ${path} is a symlink, not the pinned file"
    elif [[ -f "${fw}/${path}" ]]; then
      present+=("${path}")
    elif [[ -e "${fw}/${path}" ]]; then
      die "${fw_pkg}: firmware file ${path} is not a regular file"
    fi
  done
  (( ${#present[@]} > 0 )) || die "${fw_pkg} is installed but none of its firmware files is present; refusing a partial tree"
  (cd "${fw}" && printf '%s\0' "${present[@]}" | xargs -0 -r sha256sum --) > "${WORK}/fw.sums" \
    || die "could not hash the installed firmware files"
  declare -A shipped=()
  checked=0
  while IFS= read -r line; do
    sum="${line:0:64}" path="${line:66}"
    [[ "${line:64:2}" == '  ' && "${fw_sum[${path}]:-}" == "${sum}" ]] \
      || die "${fw_pkg}: firmware file ${path} differs from the pinned archive"
    shipped[${path}]=1
    checked=$((checked + 1))
  done < "${WORK}/fw.sums"
  (( checked == ${#present[@]} )) || die "hashed ${checked} of ${#present[@]} present firmware files"

  declare -A total=() kept=()
  for row in "${fw_rows[@]}"; do
    IFS=$'\t' read -r path cls _ <<< "${row}"
    total[${cls}]=$(( ${total[${cls}]:-0} + 1 ))
    if [[ -n "${shipped[${path}]:-}" ]]; then kept[${cls}]=$(( ${kept[${cls}]:-0} + 1 )); fi
  done
  {
    printf 'Shipped in this image: %d of %d\n' "${#present[@]}" "${#fw_rows[@]}"
    for cls in upstream upstream-other-path armbian-changed armbian-only; do
      printf '  %5d of %5d  %s\n' "${kept[${cls}]:-0}" "${total[${cls}]:-0}" "${cls}"
    done
    printf '\n'
    for row in "${fw_rows[@]}"; do
      IFS=$'\t' read -r path cls cover <<< "${row}"
      if [[ -n "${shipped[${path}]:-}" ]]; then state=shipped; else state=removed; fi
      printf '%s\t%s\t%s\t%s\n' "${state}" "${cls}" "${path}" "${cover}"
    done
    printf '%s\n' "${RULE}"
  } > "${WORK}/coverage"
  log "${fw_pkg}: ${#present[@]} of ${#fw_rows[@]} firmware files present, all byte-identical to the pinned archive"
fi

# --- 6. Preflight every destination, then write -----------------------------------------
# Each existing component of a destination directory must be a real directory, for
# every package, before the first file is written: a file or other non-directory
# there would stop install -D after an earlier package's file was already written.
real_dirs() { # <absolute directory below DEST>
  local rest="${1#/}" dir="${DEST}"
  while [[ -n "${rest}" ]]; do
    dir+="/${rest%%/*}"
    if [[ "${rest}" == */* ]]; then rest="${rest#*/}"; else rest=''; fi
    [[ ! -L "${dir}" ]] || die "${dir} is a symlink; refusing to write through it"
    [[ ! -e "${dir}" || -d "${dir}" ]] || die "${dir} exists and is not a directory; nothing written"
  done
}
for pkg in "${installed[@]}"; do
  dir="/usr/share/doc/${pkg}"
  no_symlink_dirs "${dir}/copyright"
  [[ ! -L "${DEST}${dir}" ]] || die "${DEST}${dir} is a symlink; refusing to write through it"
  real_dirs "${dir}"
  if [[ -e "${DEST}${dir}/copyright" || -L "${DEST}${dir}/copyright" ]]; then
    die "${pkg} already has ${dir}/copyright; it now ships its own or the notices ran twice"
  fi
  cp -- "${BASE}/${pkg_payload[${pkg}]}" "${WORK}/${pkg}"
  if [[ "${pkg}" == "${fw_pkg}" ]]; then cat "${WORK}/coverage" >> "${WORK}/${pkg}"; fi
done
for pkg in "${installed[@]}"; do
  install -D -m 0644 "${WORK}/${pkg}" "${DEST}/usr/share/doc/${pkg}/copyright"
  log "wrote /usr/share/doc/${pkg}/copyright"
done
